### S — Single Responsibility Principle (SRP)

**"A class should have only ONE reason to change."**

Each class should do ONE thing well.

```python
# BAD — User class does too many things
class UserBad:
    def __init__(self, name, email):
        self.name = name
        self.email = email

    def save_to_db(self):          # Database responsibility
        pass

    def send_email(self, message):  # Email responsibility
        pass

    def generate_report(self):      # Report responsibility
        pass

# GOOD — Each class has ONE responsibility
class User:
    def __init__(self, name, email):
        self.name = name
        self.email = email

class UserRepository:
    def save(self, user: User):
        """Only database operations."""
        pass

    def find_by_id(self, user_id: int) -> User:
        pass

class EmailService:
    def send(self, to: str, message: str):
        """Only email operations."""
        pass

class UserReportGenerator:
    def generate(self, user: User) -> str:
        """Only report generation."""
        pass
```

### O — Open/Closed Principle (OCP)

**"Open for extension, closed for modification."**

Add new behavior WITHOUT changing existing code.

```python
# BAD — Adding a new shape requires modifying existing code
class AreaCalculatorBad:
    def calculate(self, shape):
        if shape.type == "circle":
            return 3.14 * shape.radius ** 2
        elif shape.type == "rectangle":
            return shape.width * shape.height
        # Adding triangle means modifying THIS function!

# GOOD — Add new shapes by creating new classes
from abc import ABC, abstractmethod

class Shape(ABC):
    @abstractmethod
    def area(self) -> float:
        pass

class Circle(Shape):
    def __init__(self, radius):
        self.radius = radius

    def area(self) -> float:
        return 3.14159 * self.radius ** 2

class Rectangle(Shape):
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def area(self) -> float:
        return self.width * self.height

# Adding Triangle — NO existing code changes!
class Triangle(Shape):
    def __init__(self, base, height):
        self.base = base
        self.height = height

    def area(self) -> float:
        return 0.5 * self.base * self.height

def total_area(shapes: list[Shape]) -> float:
    return sum(shape.area() for shape in shapes)
```

### L — Liskov Substitution Principle (LSP)

**"Subtypes must be substitutable for their base types."**

If code works with a parent class, it must also work with any child class.

```python
# BAD — Penguin breaks the contract of Bird
class Bird:
    def fly(self):
        return "Flying!"

class Penguin(Bird):
    def fly(self):
        raise Exception("Penguins can't fly!")  # Breaks LSP!

# Any code expecting Bird.fly() to work will crash with Penguin

# GOOD — Separate flying and non-flying birds
class Bird(ABC):
    @abstractmethod
    def move(self):
        pass

class FlyingBird(Bird):
    def move(self):
        return "Flying!"

class SwimmingBird(Bird):
    def move(self):
        return "Swimming!"

class Eagle(FlyingBird):
    pass

class Penguin(SwimmingBird):
    pass

# Both work with any code expecting Bird
def make_bird_move(bird: Bird):
    print(bird.move())  # Works for ALL birds
```

### I — Interface Segregation Principle (ISP)

**"Don't force clients to depend on interfaces they don't use."**

Many small interfaces are better than one big interface.

```python
# BAD — One big interface forces all implementations
class Worker(ABC):
    @abstractmethod
    def work(self): pass

    @abstractmethod
    def eat(self): pass

    @abstractmethod
    def sleep(self): pass

class Robot(Worker):
    def work(self): return "Working..."
    def eat(self): raise Exception("Robots don't eat!")  # Forced to implement!
    def sleep(self): raise Exception("Robots don't sleep!")

# GOOD — Segregated interfaces
class Workable(ABC):
    @abstractmethod
    def work(self): pass

class Eatable(ABC):
    @abstractmethod
    def eat(self): pass

class Sleepable(ABC):
    @abstractmethod
    def sleep(self): pass

class Human(Workable, Eatable, Sleepable):
    def work(self): return "Working..."
    def eat(self): return "Eating..."
    def sleep(self): return "Sleeping..."

class Robot(Workable):  # Only implements what it needs
    def work(self): return "Working..."
```

### D — Dependency Inversion Principle (DIP)

**"Depend on abstractions, not concrete implementations."**

High-level modules shouldn't depend on low-level modules. Both should depend on abstractions.

```python
# BAD — High-level depends on low-level
class MySQLDatabase:
    def query(self, sql):
        return f"MySQL: {sql}"

class UserService:
    def __init__(self):
        self.db = MySQLDatabase()  # Tightly coupled to MySQL!

    def get_user(self, user_id):
        return self.db.query(f"SELECT * FROM users WHERE id = {user_id}")

# GOOD — Depend on abstraction
class Database(ABC):
    @abstractmethod
    def query(self, sql: str): pass

class MySQLDatabase(Database):
    def query(self, sql):
        return f"MySQL: {sql}"

class PostgreSQLDatabase(Database):
    def query(self, sql):
        return f"PostgreSQL: {sql}"

class UserService:
    def __init__(self, db: Database):  # Depends on abstraction!
        self.db = db

    def get_user(self, user_id):
        return self.db.query(f"SELECT * FROM users WHERE id = {user_id}")

# Can use any database:
service_mysql = UserService(MySQLDatabase())
service_pg = UserService(PostgreSQLDatabase())
```

### 5 Exercises — SOLID

1. Refactor a class that handles user registration, email sending, AND logging into separate classes (SRP).
2. Add a new payment method (cryptocurrency) to a payment system without modifying existing code (OCP).
3. Fix a `Square(Rectangle)` class that violates LSP when `set_width` changes only width.
4. Split a large `FileHandler` interface into `Readable`, `Writable`, `Seekable` (ISP).
5. Refactor a class that creates its own database connection to accept it via injection (DIP).

### 7 Interview Questions — SOLID

**Q1: What is SOLID?**

> **A:** Five design principles: Single Responsibility, Open/Closed, Liskov Substitution, Interface Segregation, Dependency Inversion. They guide clean, maintainable, extensible OOP design.

**Q2: Give a real example of SRP violation.**

> **A:** A `User` class with `save_to_database()`, `send_email()`, `generate_pdf()`. It has 3 reasons to change. Fix: separate `UserRepository`, `EmailService`, `ReportGenerator` classes.

**Q3: How does OCP help in a growing codebase?**

> **A:** New features = new classes, not modified existing code. Less risk of breaking existing functionality. Testing: only test new classes, existing tests remain valid.

**Q4: Explain LSP with the Square-Rectangle problem.**

> **A:** If `Square` inherits from `Rectangle`, and `set_width()` also changes height (to maintain square), code expecting `Rectangle` behavior breaks. Solution: don't make Square inherit from Rectangle.

**Q5: When is ISP most important?**

> **A:** When you have clients that need different parts of an interface. Large interfaces force implementations to have useless methods. Split into role-based interfaces.

**Q6: How do you implement DIP in Python?**

> **A:** Use abstract base classes or Protocols as contracts. Inject dependencies through `__init__` (constructor injection). The caller decides which implementation to use.

**Q7: Do you always need to follow SOLID strictly?**

> **A:** No. SOLID are guidelines, not rules. Over-applying them leads to over-engineering. Apply them when they solve real problems: growing codebase, changing requirements, multiple team members.

### 8 Scenario-Based Interview Questions — SOLID

**S1:** Your microservice has a 500-line class. Which SOLID principle is violated?

> **A:** SRP — the class likely does too many things. Split by responsibility: separate data access, business logic, and presentation. Each class should be focused and small.

**S2:** Adding a new feature requires changing 10 files. Which principle is violated?

> **A:** OCP — new features should be added by creating new classes, not modifying existing ones. Use polymorphism and abstractions so new behavior plugs in.

**S3:** A mock in your test breaks because the production class interface changed. Which principle?

> **A:** DIP — your code depends on a concrete implementation instead of an abstraction. Define an interface/Protocol, mock against that. Implementation changes don't break tests.

**S4:** A subclass throws `NotImplementedError` for a parent's method. Which principle?

> **A:** LSP (child isn't substitutable) and ISP (parent interface is too broad). Fix: split the interface, or restructure the hierarchy so the child doesn't need that method.

**S5:** Your team can't test a class because it creates its own database connection. Fix?

> **A:** DIP violation. Inject the database: `def __init__(self, db: Database):`. In tests, pass a mock. In production, pass the real database.

**S6:** Every time a new report format is needed, you modify the `ReportGenerator` class. Better approach?

> **A:** OCP: Create a `ReportFormat` interface with implementations: `PDFReport`, `CSVReport`, `ExcelReport`. `ReportGenerator` accepts any `ReportFormat`. New formats = new classes.

**S7:** Your `FileProcessor` ABC has `read()`, `write()`, `compress()`, `encrypt()`. Some implementations only need `read()`. Problem?

> **A:** ISP violation. Split into: `Readable`, `Writable`, `Compressable`, `Encryptable`. Classes implement only what they need.

**S8:** A junior developer argues SOLID adds too much complexity for a small project. Are they right?

> **A:** Partially. For a small script, full SOLID is overkill. For a growing project with a team, SOLID prevents technical debt. Start simple, apply SOLID principles as complexity grows.

**"Create objects without specifying the exact class."**

### Example 1 — Simple Factory

```python
from abc import ABC, abstractmethod

class Notification(ABC):
    @abstractmethod
    def send(self, message: str) -> str:
        pass

class EmailNotification(Notification):
    def send(self, message):
        return f"Email: {message}"

class SMSNotification(Notification):
    def send(self, message):
        return f"SMS: {message}"

class PushNotification(Notification):
    def send(self, message):
        return f"Push: {message}"

class NotificationFactory:
    _creators = {
        "email": EmailNotification,
        "sms": SMSNotification,
        "push": PushNotification,
    }

    @classmethod
    def create(cls, notification_type: str) -> Notification:
        creator = cls._creators.get(notification_type)
        if not creator:
            raise ValueError(f"Unknown type: {notification_type}")
        return creator()

    @classmethod
    def register(cls, name: str, creator):
        """Extend without modifying — Open/Closed Principle!"""
        cls._creators[name] = creator

# Usage
notif = NotificationFactory.create("email")
print(notif.send("Hello!"))  # "Email: Hello!"

# Register new type at runtime — no factory modification!
class SlackNotification(Notification):
    def send(self, message):
        return f"Slack: {message}"

NotificationFactory.register("slack", SlackNotification)
print(NotificationFactory.create("slack").send("Hi!"))  # "Slack: Hi!"
```

### Example 2 — Factory with Configuration

```python
from dataclasses import dataclass

@dataclass
class DatabaseConfig:
    host: str
    port: int
    database: str

def create_database(db_type: str, config: DatabaseConfig):
    factories = {
        "postgresql": lambda c: f"PostgreSQL connection to {c.host}:{c.port}/{c.database}",
        "mysql": lambda c: f"MySQL connection to {c.host}:{c.port}/{c.database}",
        "sqlite": lambda c: f"SQLite connection to {c.database}",
    }
    factory = factories.get(db_type)
    if not factory:
        raise ValueError(f"Unsupported database: {db_type}")
    return factory(config)

config = DatabaseConfig("localhost", 5432, "myapp")
print(create_database("postgresql", config))
```

### Example 3 — Abstract Factory

```python
class UIFactory(ABC):
    @abstractmethod
    def create_button(self): pass

    @abstractmethod
    def create_textbox(self): pass

class WindowsFactory(UIFactory):
    def create_button(self):
        return "Windows Button"

    def create_textbox(self):
        return "Windows TextBox"

class MacFactory(UIFactory):
    def create_button(self):
        return "Mac Button"

    def create_textbox(self):
        return "Mac TextBox"

def build_ui(factory: UIFactory):
    button = factory.create_button()
    textbox = factory.create_textbox()
    return f"UI: {button}, {textbox}"

print(build_ui(WindowsFactory()))  # "UI: Windows Button, Windows TextBox"
print(build_ui(MacFactory()))       # "UI: Mac Button, Mac TextBox"
```

**"Define a family of algorithms and make them interchangeable."**

### Example 1 — Pythonic Strategy (Functions)

```python
from typing import Callable

def quick_sort(data: list) -> list:
    if len(data) <= 1:
        return data
    pivot = data[0]
    less = [x for x in data[1:] if x <= pivot]
    greater = [x for x in data[1:] if x > pivot]
    return quick_sort(less) + [pivot] + quick_sort(greater)

def bubble_sort(data: list) -> list:
    data = data.copy()
    n = len(data)
    for i in range(n):
        for j in range(0, n - i - 1):
            if data[j] > data[j + 1]:
                data[j], data[j + 1] = data[j + 1], data[j]
    return data

class DataProcessor:
    def __init__(self, sort_strategy: Callable = sorted):
        self.sort_strategy = sort_strategy  # Inject strategy

    def process(self, data: list) -> list:
        return self.sort_strategy(data)

# Swap algorithms at runtime!
processor = DataProcessor(quick_sort)
print(processor.process([3, 1, 4, 1, 5]))

processor.sort_strategy = bubble_sort  # Change strategy
print(processor.process([3, 1, 4, 1, 5]))
```

**"Add behavior to objects dynamically without modifying their class."**

### Example 1 — Wrapping Objects

```python
class TextProcessor:
    def process(self, text: str) -> str:
        return text

class UpperCaseDecorator:
    def __init__(self, processor):
        self._processor = processor

    def process(self, text: str) -> str:
        result = self._processor.process(text)
        return result.upper()

class TrimDecorator:
    def __init__(self, processor):
        self._processor = processor

    def process(self, text: str) -> str:
        result = self._processor.process(text)
        return result.strip()

class ExclamationDecorator:
    def __init__(self, processor):
        self._processor = processor

    def process(self, text: str) -> str:
        result = self._processor.process(text)
        return result + "!"

# Stack decorators — order matters!
processor = TextProcessor()
processor = TrimDecorator(processor)
processor = UpperCaseDecorator(processor)
processor = ExclamationDecorator(processor)

print(processor.process("  hello world  "))  # "HELLO WORLD!"
```

**"Make incompatible interfaces work together."**

### Example 1 — Adapting Third-Party Libraries

```python
# Old payment system
class OldPaymentSystem:
    def make_payment(self, amount_in_cents):
        return f"Old system: paid {amount_in_cents} cents"

# New payment system expects dollars
class PaymentAdapter:
    def __init__(self, old_system):
        self._old_system = old_system

    def pay(self, amount_in_dollars):
        """Adapts dollar amount to cents."""
        cents = int(amount_in_dollars * 100)
        return self._old_system.make_payment(cents)

# New code works with the adapter
adapter = PaymentAdapter(OldPaymentSystem())
print(adapter.pay(29.99))  # "Old system: paid 2999 cents"
```

**"Abstract data access logic behind a clean interface."**

### Example 1 — Generic Repository

```python
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import Optional

@dataclass
class User:
    id: Optional[int] = None
    name: str = ""
    email: str = ""

class UserRepository(ABC):
    @abstractmethod
    def get(self, user_id: int) -> Optional[User]: pass

    @abstractmethod
    def save(self, user: User) -> User: pass

    @abstractmethod
    def delete(self, user_id: int) -> bool: pass

    @abstractmethod
    def list_all(self) -> list[User]: pass

class InMemoryUserRepository(UserRepository):
    def __init__(self):
        self._users = {}
        self._next_id = 1

    def get(self, user_id):
        return self._users.get(user_id)

    def save(self, user):
        if user.id is None:
            user.id = self._next_id
            self._next_id += 1
        self._users[user.id] = user
        return user

    def delete(self, user_id):
        return self._users.pop(user_id, None) is not None

    def list_all(self):
        return list(self._users.values())

# Usage — business logic doesn't know about storage
class UserService:
    def __init__(self, repo: UserRepository):
        self.repo = repo

    def create_user(self, name, email):
        user = User(name=name, email=email)
        return self.repo.save(user)

    def get_user(self, user_id):
        user = self.repo.get(user_id)
        if not user:
            raise ValueError(f"User {user_id} not found")
        return user

# In tests: InMemoryUserRepository
# In production: PostgresUserRepository, MongoUserRepository, etc.
```
